"minItems\":1,\"maxItems\":3,\"uniqueItems\":true,\"items\":{\"$ref\":\"#/$defs/ProviderObjectAction\"}},\"objectKey\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1024,\"pattern\":\"^[A-Za-z0-9._-]+$\",\"description\":\"`s3-static-presign` only: the object's name within `prefix`. The presigned URL names `prefix` + `objectKey` and nothing else, and `actions` must hold exactly one action.\"},\"scopes\":{\"type\":\"array\",\"maxItems\":64,\"uniqueItems\":true,\"items\":{\"type\":\"string\",\"maxLength\":256,\"pattern\":\"^[!#-\\\\[\\\\]-~]+$\"},\"description\":\"`oauth2-private-key-jwt` only: the OAuth scopes requested.\"}}},\"ProviderObjectAction\":{\"title\":\"ProviderObjectAction\",\"type\":\"string\",\"enum\":[\"put\",\"get\",\"delete\"],\"description\":\"`put`: write an object. `get`: read one. `delete`: remove one. No list, ACL, policy or bucket-level action exists here, so none can be granted.\"},\"ProviderObjectPrefix\":{\"title\":\"ProviderObjectPrefix\",\"type\":\"string\",\"minLength\":2,\"maxLength\":512,\"pattern\":\"^([a-z0-9][a-z0-9._-]{0,127}/){1,16}$\",\"description\":\"An object-key prefix within the account's bucket: one or more segments of lowercase letters, digits, `.`, `_` and `-`, each beginning with a letter or digit and ending with `/`. No quote, backslash, wildcard, whitespace, `..` segment or empty segment can appear. That is deliberate: the custodian places this value inside a provider policy — an IAM session policy (JSON), a GCS Credential Access Boundary condition (CEL) — and a value able to carry a metacharacter can break out of the string it is placed in and widen the policy. That is a known class of defect (CVE-2026-42811, a CEL injection in downscoped GCS credentials). Even with this pattern, a custodian MUST build provider policies with the provider language's own encoder, never by string interpolation.\"},\"AccountId\":{\"title\":\"AccountId\",\"type\":\"string\",\"minLength\":1,\"maxLength\":64,\"pattern\":\"^[a-z0-9][a-z0-9-]*$\",\"description\":\"The account's identifier within its context, chosen by whoever creates it. Lowercase letters, digits and hyphens, so that it can be embedded in a certificate subject, a token subject or a provider-side condition without escaping. Unique per context; never reused after deletion while anything that names it (a provider-side trust policy, an audit row) may still exist.\"},\"AccountContextId\":{\"title\":\"AccountContextId\",\"type\":\"string\",\"minLength\":1,\"maxLength\":256,\"description\":\"The custodian context that owns the account. Act scope in this context decides who may manage the account and who may consume it; the account's keys are derived in this context's key space.\"}}}"

// Spec is the SPEC §7.2 policy for the request variant, taken from this
// specification's front matter. Pass it to trusttasks.ConsumeInbound — items 5b,
// 7 and 8 are per-specification and cannot be derived from the document alone,
// and item 2 needs the schema it carries.
var Spec = trusttasks.SpecPolicy{
	TypeURI:             TypeURI,
	IsBearer:            false,
	IsProofRequired:     true,
	IsRecipientRequired: true,
	IsIssuedAtRequired:  true,
	PayloadSchema:       PayloadSchemaJSON,
}

// ResponseSpec is the SPEC §7.2 policy for the success-response variant.
// IsRecipientRequired tracks the *issuer* party's requirement, because a response
// swaps the parties (§7.3 item 5).
var ResponseSpec = trusttasks.SpecPolicy{
	TypeURI:             ResponseTypeURI,
	IsBearer:            false,
	IsProofRequired:     true,
	IsRecipientRequired: true,
	IsIssuedAtRequired:  true,
	PayloadSchema:       ResponsePayloadSchemaJSON,
}
